insert into pb_ai.eval_runs(run, fn, label, k, ids, cases) select '1121-lib7b-r8', 'ai-next', 'lib7b round 8 (fresh) + strictest + re-asks', (o - 1)::int, array(select x->>'id' from jsonb_array_elements(e) x), e from jsonb_array_elements($j$[[{"id":"st7-01","q":"At what depth do I need shoring or a trench box?","where":"Spokane, WA","level":"pipelayer"},{"id":"st7-02","q":"Can we cut Type A at 1/2 to 1 since the trench is 10 feet deep and only open one day?","where":"Tacoma, WA","level":"pipelayer"},{"id":"st7-03","q":"How fast do I have to report a worker admitted to the hospital?","where":"Salt Lake City, UT","level":"foreman"}],[{"id":"st7-04","q":"What CO reading on the gas meter is too high for a manhole entry?","where":"Fresno, CA","level":"foreman"},{"id":"st7-05","q":"At what temperature do we have to put up shade for the crew?","where":"Bakersfield, CA","level":"foreman"},{"id":"st7-06","q":"What is the minimum wage I have to pay a new laborer?","where":"Savannah, GA","level":"office"}],[{"id":"st7-07","q":"What is the minimum wage for a laborer on our job?","where":"Casper, WY","level":"office"},{"id":"st7-08","q":"At what depth do I need shoring or a trench box?","where":"Phoenix, AZ","level":"pipelayer"},{"id":"st7-09","q":"How far apart do the ladders have to be in the trench?","where":"Reno, NV","level":"pipelayer"}],[{"id":"st7-10","q":"After how many hours a week do I owe overtime?","where":"Houston, TX","level":"office"},{"id":"st7-11","q":"At what depth do I need shoring or a trench box?","where":"Oakland, CA","level":"pipelayer"},{"id":"st7-12","q":"What is the minimum wage for laborers on our job?","where":"Seattle, WA","level":"office"}]]$j$::jsonb) with ordinality t(e, o);
insert into pb_ai.eval_runs(run, fn, label, k, ids, cases) with s as (select *, (row_number() over (order by id) - 1) / 3 g from pb_ai.eval_set where id = any(array['lib-pa-dig-1','lib-il-dig-3','lib-pa-dig-3','lib-il-dig-4','lib-pa-dig-4','lib-wy-dig-1','lib-mn-dig-3','lib-nj-dig-1','lib-ma-dig-2','lib-wy-dig-3','lib-nj-dig-2','lib-ri-dig-3','lib-wy-dig-2','lib-dc-dig-1','lib-nj-dig-3','lib-mn-sp-5','lib-ma-sp-2','lib-mn-sp-6','lib-wa-sp-11','lib-wa-fup-2','lib-wa-fup-4','lib-wa-fup-5','lib-md-sp-4','lib-md-sp-2','lib-md-sp-5','lib-va-sp-5','lib-va-sp-6','lib-ca-sp-16','lib-or-sp-1','lib-ca-sp-14','lib-us-osha-65','lib-us-osha-17','lib-us-osha-76','lib-us-osha-49','lib-us-osha-7','lib-us-osha-38','lib-us-osha-46','lib-us-osha-6','lib-us-osha-28','lib-ak-tc-3','lib-ak-tc-1','lib-ma-tc-2','lib-us-mutcd-64','lib-us-mutcd-10','lib-mt-tc-1','lib-us-mutcd-26','lib-tn-tc-1','lib-us-mutcd-14','lib-us-mutcd-2','lib-us-mutcd-46','lib-tx-tc-3','lib-us-mutcd-50','lib-us-mutcd-19','lib-mt-tc-2','lib-ut-spec-1','lib-ut-spec-2','lib-ga-spec-1','lib-us-std-12','lib-ga-spec-2','lib-oh-spec-1','lib-oh-spec-2','lib-us-std-8','lib-us-pipe-2','lib-us-fed-4','lib-us-fed-24','lib-tx-env-1','lib-us-pipe-1','lib-us-fed-1','lib-tx-row-1','lib-fl-row-1','lib-fl-spec-more-1','lib-us-em-1','lib-us-em-2','lib-us-osha-1','lib-us-osha-42','lib-wa-fup-1','lib-us-osha-48','lib-us-osha-55','lib-us-mutcd-54','lib-us-fed-11','lib-us-fed-19','tr3','cs1','pm1','nw13','em1','ng2','nw1','nw14','sa1','gn1','lib-us-osha-62','lib-us-mutcd-40','lib-us-mutcd-55','lib-us-fed-17','lib-us-mutcd-15','lib-us-osha-12','lib-mt-dig-1','lib-ny-sp-1','lib-us-fed-9','lib-ut-sp-1','lib-in-dig-2','ph08','tr12','tr14']))
  select '1121-lib7b-r8', 'ai-next', 'lib7b round 8 (fresh) + strictest + re-asks', 1000 + g, array_agg(id), jsonb_agg(jsonb_build_object('id', id, 'q', q, 'where', "where", 'level', level)
      || case when images is null then '{}'::jsonb else jsonb_build_object('images', images) end
      || case when image_ids is null then '{}'::jsonb else jsonb_build_object('image_ids', to_jsonb(image_ids)) end
      || case when feature is null then '{}'::jsonb else jsonb_build_object('feature', feature) end
      || case when model is null then '{}'::jsonb else jsonb_build_object('model', model) end) from s group by g;
select pb_ai.eval_pump('1121-lib7b-r8') started, (select count(*) from pb_ai.eval_runs where run = '1121-lib7b-r8') batches;
